import{_ as a,o,c as n,aa as d}from"./chunks/framework.BAs_AphD.js";const p="/buildary-help-preview/academy/img/podepsani-dne/05.webp",i="/buildary-help-preview/academy/img/podepsat-vice-dni/05.webp",t="/buildary-help-preview/academy/img/podpis-dalsiho-zaznamu/01.webp",z=JSON.parse('{"title":"Podepisování deníku","description":"","frontmatter":{"title":"Podepisování deníku","wiki":"cs:diary:signing"},"headers":[],"relativePath":"diary/signing.md","filePath":"diary/signing.md","lastUpdated":1794209661000}'),s={name:"diary/signing.md"};function r(l,e,u,v,m,h){return o(),n("div",null,[...e[0]||(e[0]=[d('<h1 id="podepisovani-deniku" tabindex="-1">Podepisování deníku <a class="header-anchor" href="#podepisovani-deniku" aria-label="Permalink to &quot;Podepisování deníku&quot;">​</a></h1><p>Podpisem den v deníku uzamknete – jeho záznamy už nikdo nezmění. Podepisuje se celý den (Denní protokol) a zvlášť každý Další záznam.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/podepsani-dne">Podepsat den v deníku</a>, <a href="/buildary-help-preview/akademie/podepsat-vice-dni">Podepsat více dní najednou</a> a <a href="/buildary-help-preview/akademie/podpis-dalsiho-zaznamu">Podepsat jednotlivý zápis</a> v Akademii.</p><h2 id="nez-zacnete" tabindex="-1">Než začnete <a class="header-anchor" href="#nez-zacnete" aria-label="Permalink to &quot;Než začnete&quot;">​</a></h2><ul><li><strong>Nastavte si způsob podpisu</strong> v uživatelském menu → <strong>Nastavení podpisu</strong>. Bez něj podepsat nejde. Který způsob zvolit, popisují <a href="/buildary-help-preview/diary/signaturesetting">Způsoby podpisu</a>.</li><li>Deník vedený podle stavebního zákona podepisujte <strong>kvalifikovaným certifikátem</strong>. Proč, vysvětlují <a href="/buildary-help-preview/diary/signaturesetting#proc-uznavany-podpis">Způsoby podpisu – Proč uznávaný podpis</a>.</li><li>Nemáte-li elektronický podpis, postupujte podle stránky <a href="/buildary-help-preview/diary/signingwithout">Bez elektronického podpisu</a>.</li></ul><h2 id="co-se-podepisuje" tabindex="-1">Co se podepisuje <a class="header-anchor" href="#co-se-podepisuje" aria-label="Permalink to &quot;Co se podepisuje&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Co</th><th>Kde</th><th>Co podpis uzamkne</th></tr></thead><tbody><tr><td><strong>Den</strong> (Denní protokol)</td><td>tlačítko <strong>Podepsat</strong> nad denními záznamy</td><td>celý den se všemi sekcemi</td></tr><tr><td><strong>Další záznam</strong></td><td>tlačítko <strong>Podepsat</strong> u záznamu</td><td>jen tento záznam</td></tr></tbody></table><p>Den se uzamkne <strong>prvním podpisem</strong>. Další osoby (například technický dozor stavebníka) pak podepisují už uzamčený den a jejich podpisy se k němu přidávají. Počet podpisů vidíte v kalendářní liště u každého dne. Kolik podpisových polí má Denní protokol, určuje pole <strong>Počet podpisů</strong> v <a href="/buildary-help-preview/diary/diarysettings#podpisy">Nastavení deníku</a>.</p><h2 id="podepsat-den" tabindex="-1">Podepsat den <a class="header-anchor" href="#podepsat-den" aria-label="Permalink to &quot;Podepsat den&quot;">​</a></h2><p>Před podpisem si den prohlédněte tlačítkem <strong>Náhled PDF</strong> – takto bude den vypadat v deníku. Pak klikněte na <strong>Podepsat</strong> a potvrďte. Co se stane dál, záleží na <a href="/buildary-help-preview/diary/signaturesetting">způsobu podpisu</a>: Buildary certifikátem se den podepíše hned, při podpisu v externí aplikaci si PDF stáhnete a podepsané ho nahrajete zpět (viz <a href="/buildary-help-preview/diary/externalappsignature">Podpis v externí aplikaci</a>).</p><figure class="shot" style="--w:760px;"><img src="'+p+'" alt="Podepsaný den: zelený pruh pod dnem v kalendářní liště a počet podpisů 1" loading="lazy"><figcaption>Podepsaný den má v kalendářní liště zelený pruh, číslo udává počet podpisů.</figcaption></figure><p>Co znamenají barvy pruhu pod dnem v kalendářní liště, popisují <a href="/buildary-help-preview/diary/dailyentries#co-znamenaji-barvy-a-ikony-dne">Denní záznamy – barvy dne</a>.</p><h3 id="kdo-podepisuje-a-v-jakem-poradi" tabindex="-1">Kdo podepisuje a v jakém pořadí <a class="header-anchor" href="#kdo-podepisuje-a-v-jakem-poradi" aria-label="Permalink to &quot;Kdo podepisuje a v jakém pořadí&quot;">​</a></h3><ul><li><strong>Jako první podepisuje den ten, kdo deník vede</strong> – obvykle stavbyvedoucí zhotovitele, který zapisuje denní záznamy (kompetence <strong>Pravidelné záznamy</strong>). Sám tak určuje, kdy se den uzamkne. Technický dozor stavebníka a další osoby podepisují až po něm.</li><li>Role a kompetence oprávněných osob popisuje <a href="/buildary-help-preview/diary/userpermissions">Kdo co smí v deníku</a>.</li></ul><h3 id="dny-se-podepisuji-postupne" tabindex="-1">Dny se podepisují postupně <a class="header-anchor" href="#dny-se-podepisuji-postupne" aria-label="Permalink to &quot;Dny se podepisují postupně&quot;">​</a></h3><p>Zapisovat můžete do dnů v libovolném pořadí, ale <strong>podepisovat jen navazující dny</strong>: den musí navazovat na poslední podepsaný den. Dny, kdy se nepracovalo (včetně víkendů), proto označte v <strong>Dalších volbách</strong> jako <strong>Nepracovní den (bez záznamů)</strong> – viz <a href="/buildary-help-preview/diary/dailyentries">Denní záznamy</a>.</p><div class="warning custom-block"><p class="custom-block-title">První podepsaný den</p><p>Podepisovat začněte opravdu prvním dnem deníku – datem zavedení deníku z <a href="/buildary-help-preview/diary/diaryidentification#uvodni-list-deniku">Úvodního listu deníku</a>. Jakmile první den podepíšete, už před něj nevložíte žádné denní záznamy.</p></div><h3 id="kdy-podepisovat" tabindex="-1">Kdy podepisovat <a class="header-anchor" href="#kdy-podepisovat" aria-label="Permalink to &quot;Kdy podepisovat&quot;">​</a></h3><p>Záznamy zapisujte a podepisujte průběžně – zákonnou lhůtu pro zápis a to, jak ji Buildary hlídá, popisuje <a href="/buildary-help-preview/diary/diarysettings#cas-porizeni-zaznamu">Čas pořízení záznamu</a>.</p><h2 id="podepsat-vice-dni-najednou" tabindex="-1">Podepsat více dní najednou <a class="header-anchor" href="#podepsat-vice-dni-najednou" aria-label="Permalink to &quot;Podepsat více dní najednou&quot;">​</a></h2><p>V <strong>Dalších volbách</strong> zvolte <strong>Podepsat více dní</strong>, v kalendáři klikněte na první a poslední den a potvrďte tlačítkem <strong>Podepsat</strong>.</p><ul><li>Najednou podepíšete nejvýše <strong>31 po sobě jdoucích dní</strong>.</li><li>První den musí navazovat na poslední podepsaný den. Může to být i den už podepsaný – když k podepsaným dnům přidáváte další podpis.</li></ul><figure class="shot" style="--w:640px;"><img src="'+i+'" alt="Okno pro podepsání více dnů s polem První den k podpisu a Poslední den k podpisu" loading="lazy"></figure><h2 id="podepsat-dalsi-zaznam" tabindex="-1">Podepsat Další záznam <a class="header-anchor" href="#podepsat-dalsi-zaznam" aria-label="Permalink to &quot;Podepsat Další záznam&quot;">​</a></h2><p>Stejně jako v papírovém deníku si každý svůj Další záznam podepisuje jeho autor. U záznamu klikněte na <strong>Podepsat</strong>. Podpis záznam uzamkne – upravit ho pak už nejde, doplnění napište jako reakci nebo nový záznam.</p><figure class="shot" style="--w:760px;"><img src="'+t+'" alt="Další záznam s tlačítky Upravit, Podepsat, Reagovat a Další volby" loading="lazy"></figure><p>Pokud autor elektronický podpis nemá, uzamkne záznam nahraným skenem – viz <a href="/buildary-help-preview/diary/signingwithout">Bez elektronického podpisu</a>.</p><h2 id="kontrola-podpisu-dalsich-zaznamu" tabindex="-1">Kontrola podpisů Dalších záznamů <a class="header-anchor" href="#kontrola-podpisu-dalsich-zaznamu" aria-label="Permalink to &quot;Kontrola podpisů Dalších záznamů&quot;">​</a></h2><p>Den nejde podepsat, dokud jsou v něm <strong>nepodepsané Další záznamy jiných autorů</strong>. Buildary podpis dne odmítne a ohlásí, že záznamy nejsou podepsané. Nechte je nejdřív podepsat jejich autory.</p><p>Své vlastní Další záznamy podepisovat nemusíte, pokud podepisujete i den – podpisem dne je stvrdíte.</p><p>Kontrolu lze vypnout: v <a href="/buildary-help-preview/diary/diarysettings">Nastavení deníku</a> na záložce <strong>Základní</strong> zrušte zaškrtnutí <strong>Kontrolovat podpis</strong> u položky <strong>Kontrolovat podpisy Dalších záznamů</strong>. Ve výchozím stavu je kontrola zapnutá.</p><h2 id="docasny-zamek-a-casovy-limit" tabindex="-1">Dočasný zámek a časový limit <a class="header-anchor" href="#docasny-zamek-a-casovy-limit" aria-label="Permalink to &quot;Dočasný zámek a časový limit&quot;">​</a></h2><p>Pokud podpis neproběhne okamžitě (typicky při podpisu v externí aplikaci), den nebo záznam se po stažení k podpisu <strong>dočasně zamkne</strong> – žlutý zámek. Nikdo ho do té doby nemůže měnit, aby se podepsal přesně ten obsah, který jste stáhli.</p><p>Podpis musíte dokončit v <strong>časovém limitu</strong> nastaveném v <a href="/buildary-help-preview/diary/diarysettings">Nastavení deníku</a> (pole <strong>Časový limit pro podpis</strong>). Když ho nestihnete, dočasný zámek se zruší, záznamy jdou zase upravovat a pozdě nahraný soubor Buildary odmítne. Podpis pak začněte znovu stažením.</p><h2 id="podepisovat-v-mobilu" tabindex="-1">Podepisovat v mobilu <a class="header-anchor" href="#podepisovat-v-mobilu" aria-label="Permalink to &quot;Podepisovat v mobilu&quot;">​</a></h2><p>V mobilní aplikaci podepisujete stejně a se stejným nastavením podpisu jako na webu – viz <a href="/buildary-help-preview/diary/m_signing">Podepisování v mobilu</a>.</p>',36)])])}const c=a(s,[["render",r]]);export{z as __pageData,c as default};
